   [60]={next_id=61, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="早在黎苏根帮助奥莉维娅之后，你就已经知道了这位克罗瓦德权倾朝野的公爵。此刻，整齐排布的十字党成员正中心，有一个明显的空位。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT209_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
