   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“铁血大臣”的登场显然让所有人都吃了一惊，但老者并没有理会众人的惊讶，一步一个脚印地在踏上演讲台。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT209_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
