   [72]={next_id=73, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="全场立刻安静下来，所有目光集中在他身上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT209_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="议长先生因身体抱恙，今日无法主持议程。受高奈莉娅·冯·霍亨索伦皇女殿下委托，由我暂代其职，主持本次会议。", msg_color="", msg_size=0, talker="维特伯爵", audio="", img="arts/ui/bg/story/storybg_ACT209_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7193", 0, 0, 21.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [74]={next_id=75, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他没有任何多余的寒暄或解释，语气平淡却带着不容置疑的权威。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT209_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
