   [297]={next_id=298, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="更何况，自从殿下您下令放逐了菲利普六世以来，您就是最后一位皇室成员了。", msg_color="", msg_size=0, talker="黑斯廷斯公爵", audio="", img="arts/ui/bg/story/storybg_ACT209_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [298]={next_id=299, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="您是让“曙光革命”几乎零牺牲成功的功臣之一，我们自然是不会怀疑您的。", msg_color="", msg_size=0, talker="黑斯廷斯公爵", audio="", img="arts/ui/bg/story/storybg_ACT209_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [299]={next_id=300, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可是，如果您希望将强大的战力集合起来，统帅他们完成您的计划，那就需要一个足够正统、足够强力的约束。", msg_color="", msg_size=0, talker="黑斯廷斯公爵", audio="", img="arts/ui/bg/story/storybg_ACT209_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
